class Solution {
public:
    vector<int> maximumSubarrayXor(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<vector<int>> f(n, vector<int>(n, 0));
        for (int i = 0; i < n; ++i) f[i][i] = nums[i];
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                f[i][j] = f[i][j - 1] ^ f[i + 1][j];
            }
        }
        vector<vector<int>> mx(n, vector<int>(n, 0));
        for (int i = 0; i < n; ++i) mx[i][i] = nums[i];
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                mx[i][j] = max({f[i][j], mx[i + 1][j], mx[i][j - 1]});
            }
        }
        vector<int> ans;
        for (const auto& q : queries) {
            ans.push_back(mx[q[0]][q[1]]);
        }
        return ans;
    }
};

class Solution {
    public int[] maximumSubarrayXor(int[] nums, int[][] queries) {
        int n = nums.length;
        int[][] f = new int[n][n];
        for (int i = 0; i < n; ++i) f[i][i] = nums[i];
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                f[i][j] = f[i][j - 1] ^ f[i + 1][j];
            }
        }
        int[][] mx = new int[n][n];
        for (int i = 0; i < n; ++i) mx[i][i] = nums[i];
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                mx[i][j] = Math.max(f[i][j], Math.max(mx[i + 1][j], mx[i][j - 1]));
            }
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            ans[i] = mx[queries[i][0]][queries[i][1]];
        }
        return ans;
    }
}

var maximumSubarrayXor = function(nums, queries) {
    const n = nums.length;
    const f = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) f[i][i] = nums[i];
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i <= n - len; i++) {
            const j = i + len - 1;
            f[i][j] = f[i][j - 1] ^ f[i + 1][j];
        }
    }
    const mx = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) mx[i][i] = nums[i];
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i <= n - len; i++) {
            const j = i + len - 1;
            mx[i][j] = Math.max(f[i][j], mx[i + 1][j], mx[i][j - 1]);
        }
    }
    return queries.map(([l, r]) => mx[l][r]);
};
